package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.NumberIsTooCloseToZeroException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.Mockito.when;

public class BrentSolver_solve_TriageGen0Test {

    private BrentSolver solver;
    private static final double EPSILON = 1e-6;

    @Mock
    private UnivariateRealFunction function;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        solver = new BrentSolver();
    }

    /**
     * Tests the case where the initial guess is already a root.
     * Covers: if (Math.abs(yInitial) <= functionValueAccuracy)
     */
    @Test
    public void testSolve_InitialIsRoot() throws Exception {
        double initial = 1.0;
        when(function.value(initial)).thenReturn(0.0);

        double result = solver.solve(function, 0.0, 2.0, initial);
        assertEquals(initial, result, EPSILON);
    }

    /**
     * Tests the case where the minimum endpoint is a root.
     * Covers: if (Math.abs(yMin) <= functionValueAccuracy)
     */
    @Test
    public void testSolve_MinIsRoot() throws Exception {
        double min = 0.0;
        double initial = 1.0;
        double max = 2.0;
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);
        assertEquals(min, result, EPSILON);
    }

    /**
     * Tests the case where the initial guess and min bracket the root.
     * Covers: if (yInitial * yMin < 0)
     */
    @Test
    public void testSolve_InitialAndMinBracket() throws Exception {
        double min = 0.0;
        double initial = 1.0;
        double max = 2.0;
        // yInitial = 1, yMin = -1 -> bracketed
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(-1.0);
        // Mocking a simple linear function f(x) = x - 0.5, root at 0.5
        // But since the code enters a recursive call with different params, 
        // we rely on the solver's logic to eventually resolve.
        // For simplicity in a unit test of this specific branch, we use a simple function.
        UnivariateRealFunction simpleFunc = x -> x - 0.5;

        double result = solver.solve(simpleFunc, min, max, initial);
        assertEquals(0.5, result, EPSILON);
    }

    /**
     * Tests the case where the maximum endpoint is a root.
     * Covers: if (Math.abs(yMax) <= functionValueAccuracy)
     */
    @Test
    public void testSolve_MaxIsRoot() throws Exception {
        double min = 0.0;
        double initial = 1.0;
        double max = 2.0;
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(1.0);
        when(function.value(max)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);
        assertEquals(max, result, EPSILON);
    }

    /**
     * Tests the case where the initial guess and max bracket the root.
     * Covers: if (yInitial * yMax < 0)
     */
    @Test
    public void testSolve_InitialAndMaxBracket() throws Exception {
        double min = 0.0;
        double initial = 1.0;
        double max = 2.0;
        // yInitial = 1, yMax = -1 -> bracketed
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(1.0);
        when(function.value(max)).thenReturn(-1.0);

        UnivariateRealFunction simpleFunc = x -> 1.5 - x; // root at 1.5
        double result = solver.solve(simpleFunc, min, max, initial);
        assertEquals(1.5, result, EPSILON);
    }

    /**
     * Tests the case where the min and max have the same sign (not bracketed).
     * Covers: if (yMin * yMax > 0)
     */
    @Test
    public void testSolve_NoBracketingThrowsException() throws Exception {
        double min = 0.0;
        double initial = 1.0;
        double max = 2.0;
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(1.0);
        when(function.value(max)).thenReturn(1.0);

        assertThrows(IllegalArgumentException.class, () -> {
            solver.solve(function, min, max, initial);
        });
    }

    /**
     * Tests the full Brent algorithm path.
     * Covers: the final return solve(f, min, yMin, max, yMax, initial, yInitial);
     */
    @Test
    public void testSolve_FullBrentAlgorithm() throws Exception {
        // f(x) = x^2 - 2, root at sqrt(2) approx 1.41421356
        UnivariateRealFunction f = x -> x * x - 2.0;
        double min = 0.0;
        double max = 2.0;
        double initial = 1.5;

        double result = solver.solve(f, min, max, initial);
        assertEquals(Math.sqrt(2.0), result, EPSILON);
    }

    /**
     * Tests the validation of the sequence (min, initial, max).
     * Covers: verifySequence(min, initial, max)
     */
    @Test
    public void testSolve_InvalidSequenceThrowsException() {
        // If initial is not between min and max, verifySequence should fail
        assertThrows(IllegalArgumentException.class, () -> {
            solver.solve(x -> x, 2.0, 1.0, 1.5);
        });
    }
}
